from cardio_1 import a, G
# K21 — Reflux gastro-œsophagien (G-04-Gastroentérologie et hépatologie). Clés absentes du glossaire au 09.10.2026.
a('RGO', [('R', 'Reflux'), ('G', 'Gastro-'), ('O', 'Œsophagien')], 'Reflux gastro-œsophagien (maladie de reflux gastro-œsophagien)', '<p>Maladie définie par le reflux du contenu gastrique dans l’œsophage provoquant des symptômes gênants ou des lésions (définition de Montréal, reprise par la DGVS en 2023). Équivalent anglais : GERD ou GORD.</p>', 'k21-montreal')
a('IPP', [('I', 'Inhibiteur'), ('P', 'de la Pompe'), ('P', 'à Protons')], 'Inhibiteur de la pompe à protons', '<p>Benzimidazole substitué qui bloque durablement l’H⁺/K⁺-ATPase de la cellule pariétale gastrique, voie finale de la sécrétion acide (ésoméprazole, pantoprazole, oméprazole, lansoprazole, rabéprazole).</p>', 'k21-d-ipp')
a('SIO', [('S', 'Sphincter'), ('I', 'Inférieur'), ('O', 'de l’Œsophage')], 'Sphincter inférieur de l’œsophage', '<p>Zone de muscle lisse de l’œsophage terminal qui maintient une pression de repos ; avec le pilier diaphragmatique qui l’entoure, il forme la barrière anti-reflux de la jonction œso-gastrique.</p>', 'k21-rtsio')
a('TEA', [('T', 'Temps'), ('E', 'd’Exposition'), ('A', 'Acide')], 'Temps d’exposition acide de l’œsophage', '<p>Proportion du temps d’enregistrement pendant laquelle le pH de l’œsophage distal est inférieur à 4. Hors IPP (Lyon 2.0) : moins de 4 % physiologique, 4 à 6 % non concluant, plus de 6 % pathologique. Équivalent anglais : acid exposure time (AET).</p>', 'k21-phmetrie')
a('LA', [('L', 'Los'), ('A', 'Angeles')], 'Classification de Los Angeles de l’œsophagite', '<p>Classification endoscopique de l’œsophagite de reflux en quatre grades, A à D, selon la longueur et l’extension circulaire des pertes de substance. Ici, LA ne désigne pas un article.</p>', 'k21-la')
a('OGD', [('O', 'Œso-'), ('G', 'Gastro-'), ('D', 'Duodénoscopie')], 'Œsogastroduodénoscopie', '<p>Endoscopie digestive haute qui explore l’œsophage, l’estomac et le duodénum ; dans le RGO, elle grade l’œsophagite, recherche un œsophage de Barrett et permet des biopsies.</p>', 'k21-ogd')
a('ESGE', [('E', 'European (européenne)'), ('S', 'Society of (société d’)'), ('G', 'Gastrointestinal (digestive)'), ('E', 'Endoscopy (endoscopie)')], 'Société européenne d’endoscopie digestive', '<p>Société savante européenne qui publie les recommandations d’endoscopie digestive, dont celle de 2023 sur le diagnostic et la prise en charge de l’œsophage de Barrett.</p>')
a('UEG', [('U', 'United (unie)'), ('E', 'European (européenne)'), ('G', 'Gastroenterology (gastroentérologie)')], 'United European Gastroenterology (fédération européenne de gastroentérologie)', '<p>Organisation européenne qui fédère les sociétés nationales et spécialisées de gastroentérologie ; coautrice, avec l’EAES, de la recommandation rapide de 2022 sur la chirurgie du RGO.</p>')
a('EAES', [('E', 'European (européenne)'), ('A', 'Association for (association de)'), ('E', 'Endoscopic (endoscopique)'), ('S', 'Surgery (chirurgie)')], 'Association européenne de chirurgie endoscopique', '<p>Société savante européenne de chirurgie mini-invasive ; autrice des recommandations rapides de 2022 (chirurgie du RGO, avec l’UEG) et de 2023 (hernies para-œsophagiennes).</p>')
a('DGVS', [('D', 'Deutsche (allemande)'), ('G', 'Gesellschaft für (société de)'), ('V', 'Verdauungs- (digestives)'), ('S', 'und Stoffwechselkrankheiten (et métaboliques)')], 'Société allemande de gastroentérologie, des maladies digestives et métaboliques', '<p>Société savante allemande ; autrice de la recommandation S2k sur le RGO et l’œsophagite à éosinophiles (mars 2023, version anglaise 2024).</p>')
a('H2', [('H', 'Histamine'), ('2', 'récepteur de type 2')], 'Récepteur H2 de l’histamine', '<p>Récepteur de la cellule pariétale par lequel l’histamine stimule la sécrétion acide. Les antihistaminiques H2 le bloquent ; aucune information professionnelle suisse d’antihistaminique H2 n’a été trouvée sur AmiKo au 09.10.2026.</p>')
a('LINX', [('LINX', 'nom commercial d’un anneau magnétique de renfort du sphincter, non acronyme')], 'Anneau magnétique LINX', '<p>Anneau de billes magnétiques placé par laparoscopie autour de la jonction œso-gastrique pour renforcer la barrière anti-reflux ; option ouverte par la DGVS dans des centres sélectionnés.</p>', 'k21-linx')
a('ICARUS', [('ICARUS', 'nom propre d’un consensus international de sélection des patients pour la chirurgie antireflux, non développé lettre à lettre')], 'Consensus ICARUS (2019)', '<p>Consensus Delphi de 35 experts, coordonné à Louvain, qui précise les critères cliniques et les examens nécessaires avant une chirurgie antireflux (Pauwels, Gut 2019).</p>', 'k21-icarus')
a('AspECT', [('AspECT', 'Aspirin and Esomeprazole Chemoprevention in Barrett’s metaplasia Trial (essai de chimioprévention par aspirine et ésoméprazole dans l’œsophage de Barrett)')], 'Essai AspECT (2018)', '<p>Essai randomisé factoriel de 2 557 patients porteurs de Barrett, suivis 8,9 ans : la double dose d’ésoméprazole a amélioré un critère composite (décès, dysplasie de haut grade, adénocarcinome) par rapport à la dose simple, sans groupe sans IPP.</p>', 'k21-contentieux-barrett')
a('K21.0', [('K21.0', 'code CIM-10-GM 2024')], 'Reflux gastro-œsophagien avec œsophagite', '<p>Sous-catégorie traitée dans le cours K21 — Reflux gastro-œsophagien : œsophagite peptique et œsophagite de reflux.</p>')
a('K21.9', [('K21.9', 'code CIM-10-GM 2024')], 'Reflux gastro-œsophagien sans œsophagite', '<p>Sous-catégorie traitée dans le cours K21 — Reflux gastro-œsophagien : reflux œsophagien sans autre précision.</p>')
a('K22.7', [('K22.7', 'code CIM-10-GM 2024')], 'Œsophage de Barrett', '<p>Catégorie traitée comme complication dans le cours K21 — Reflux gastro-œsophagien.</p>')
a('Hvid-Jensen', [('Hvid-Jensen', 'nom propre : Frederik Hvid-Jensen, chirurgien digestif à Aarhus, premier auteur')], 'Hvid-Jensen et collaborateurs, N Engl J Med 2011', '<p>Cohorte nationale danoise de 11 028 patients porteurs d’œsophage de Barrett (1992-2009) : risque annuel d’adénocarcinome de 0,12 %.</p>', 'k21-hvid')
a('Ness-Jensen', [('Ness-Jensen', 'nom propre : Eivind Ness-Jensen, gastroentérologue norvégien, premier auteur')], 'Ness-Jensen et collaborateurs, Am J Gastroenterol 2013', '<p>Cohorte populationnelle norvégienne de 29 610 adultes : la perte de poids réduit les symptômes de reflux de façon dose-dépendante et améliore l’efficacité des médicaments antireflux.</p>', 'k21-tour-taille')
a('El-Serag', [('El-Serag', 'nom propre : Hashem B. El-Serag, gastroentérologue et épidémiologiste, premier auteur')], 'El-Serag et collaborateurs, Gut 2014', '<p>Revue systématique de l’épidémiologie du RGO : prévalence de 8,8 à 25,9 % en Europe pour un pyrosis ou une régurgitation au moins hebdomadaire.</p>')
a('Savary-Miller', [('Savary-Miller', 'noms propres de deux endoscopistes, Marcel Savary et Guy Miller, auteurs d’une classification ancienne de l’œsophagite')], 'Classification de Savary-Miller', '<p>Ancienne classification endoscopique de l’œsophagite par stades ; la DGVS recommande de ne plus l’utiliser au profit de la classification de Los Angeles.</p>', 'k21-la')
a('Pantoprazol-Mepha', [('Pantoprazol-Mepha', 'nom commercial suisse, non développable lettre à lettre')], 'Spécialité suisse de pantoprazole (Mepha Pharma)', '<p>Comprimés gastro-résistants de pantoprazole à 20 et 40 mg dont l’information professionnelle suisse (décembre 2022) fonde les doses et les précautions citées dans ce cours.</p>', 'k21-d-pantoprazole')
